import {
  createTimeline,
  type TimelineRows,
  type TimelineSpan,
  type TimelineTick,
} from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createEffect, createSignal, For, untrack } from "solid-js";

import { t } from "./theme.ts" with { type: "cssints" };

export type { TimelineSpan };

export interface TimelineProps {
  /**
   * The spans, in display order: a root first, then its children and grandchildren. Read once, when the component is
   * created, so a trace that arrives later is the page's new `<Timeline>`.
   */
  readonly spans: ReadonlyArray<TimelineSpan>;
  /** The unit of `start` and `end`, which the ruler labels its ticks with. @default "ms" */
  readonly unit?: "ms" | "us" | "s" | undefined;
  /** The selected span's id (controlled). Omit it and the primitive keeps the selection. */
  readonly selected?: string | undefined;
  /** A selection request the host may ignore. */
  readonly onSelect?: ((id: string) => void) | undefined;
  /** The name the list announces. @default "Span timeline" */
  readonly label?: string | undefined;
  /** The primitive, once: a page that moves the selection itself. */
  readonly onReady?: ((timeline: TimelineRows) => void) | undefined;
  /** The line under the trace; left out, the keys in one sentence. */
  readonly hint?: string | undefined;
  readonly class?: string | undefined;
}

const DEFAULT_LABEL = "Span timeline";
const DEFAULT_HINT =
  "Keys: ↑ and ↓ move between spans, Home and End jump to the ends, and Enter or Space selects one.";

/** The three columns: the name, the bars' track and the duration, shared by the ruler and every row. */
const COLUMNS = "12rem minmax(0, 1fr) 4.5rem";

const rootClass = css.cn(css.display("grid"), css.gap(t.space._2));

// The frame is the surface: the radius and the border are the kit's, and the dark mode moves the tokens underneath.
const frameClass = css.cn(
  css.overflow("hidden"),
  css.boxSizing("border-box"),
  css.color(t.color.text),
  css.bg(t.color.surface),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.xl),
  css.fontSize(t.font.size),
);

const rulerRowClass = css.cn(
  css.display("grid"),
  css.gridTemplateColumns(COLUMNS),
  css.alignItems("end"),
  css.gap(t.space._3),
  css.minHeight(t.space._8),
  css.padding(t.space._1, t.space._3),
  css.boxSizing("border-box"),
  css.bg(t.color.page),
  css.borderBottom("1px solid", t.color.border),
);

const captionClass = css.cn(css.fontSize(t.font.sizeSm), css.color(t.color.muted));

// The ticks are the primitive's `rulerProps.ticks`: a line per tick, and its label on the line.
const rulerTrackClass = css.cn(
  css.position("relative"),
  css.alignSelf("stretch"),
  css.minHeight("1.5rem"),
);

const tickClass = css.cn(
  css.position("absolute"),
  css.top("0"),
  css.bottom("0"),
  css.borderInlineStart("1px solid", t.color.border),
  css.pointerEvents("none"),
);

const tickLabelClass = css.cn(
  css.position("absolute"),
  css.top("0"),
  css.padding("0", "2px"),
  css.bg(t.color.page),
  css.color(t.color.muted),
  css.fontSize("0.6875rem"),
  css.lineHeight("1.4"),
  css.whiteSpace("nowrap"),
);

const listClass = css.cn(
  css.display("grid"),
  css.margin("0"),
  css.padding("0"),
  css.listStyle("none"),
  css.lastChild(css.borderBottom("none")),
);

// Every row is one span: the name column, the track the bar is placed on, and the span's duration. The hierarchy is
// `aria-level` on the listitem and the `--depth` the primitive puts on the label, so a narrow page keeps the name whole.
const rowClass = css.cn(
  css.display("grid"),
  css.gridTemplateColumns(COLUMNS),
  css.alignItems("center"),
  css.gap(t.space._3),
  css.minHeight(t.space._9),
  css.padding(t.space._1, t.space._3),
  css.boxSizing("border-box"),
  css.borderBottom("1px solid", t.color.border),
  css.outline("none"),
  css.cursor("pointer"),
  css.group("timeline-row"),
  css.hover(css.bg(t.color.buttonBackground)),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("-2px")),
  css.attr("aria-current", "true")(
    css.bg(t.color.buttonBackgroundPressed),
    css.hover(css.bg(t.color.buttonBackgroundPressed)),
  ),
  css.media("(prefers-reduced-motion: no-preference)")(
    css.transition("background-color 120ms ease-out"),
  ),
);

const labelClass = css.cn(
  css.minWidth("0"),
  css.overflow("hidden"),
  css.whiteSpace("nowrap"),
  css.textOverflow("ellipsis"),
  css.paddingInlineStart("calc(var(--depth) * 0.75rem)"),
);

const trackClass = css.cn(
  css.position("relative"),
  css.height(t.space._2),
  css.minWidth("0"),
  css.borderRadius("999px"),
  css.bg(t.color.buttonBackground),
);

// The bar's geometry is the primitive's `left` / `width` percentages; the tone is the status it carries. `unset` stays
// the muted gray, `ok` takes the accent and `error` the invalid colour, so a failed span reads at a glance.
const barClass = css.cn(
  css.position("absolute"),
  css.top("0"),
  css.height("100%"),
  css.borderRadius("999px"),
  css.bg(t.color.muted),
  css.within(css.attr("data-status", "ok"), "timeline-row")(css.bg(t.color.highlight)),
  css.within(css.attr("data-status", "error"), "timeline-row")(css.bg(t.color.invalid)),
  css.media("(prefers-reduced-motion: no-preference)")(
    css.transition("background-color 120ms ease-out"),
  ),
);

const durationClass = css.cn(
  css.fontSize(t.font.sizeSm),
  css.color(t.color.muted),
  css.fontVariantNumeric("tabular-nums"),
  css.textAlign("end"),
  css.whiteSpace("nowrap"),
);

const statusClass = css.cn(
  css.margin("0"),
  css.padding("0", t.space._1),
  css.fontSize(t.font.sizeSm),
  css.color(t.color.text),
);

const hintClass = css.cn(
  css.margin("0"),
  css.padding("0", t.space._1),
  css.fontSize(t.font.sizeSm),
  css.color(t.color.muted),
);

/** A tick's label sits on its line: left-aligned at the start, centred in the middle and ending at the last tick. */
const tickShift = (index: number, count: number): string =>
  index === 0 ? "translateX(0)" : index === count - 1 ? "translateX(-100%)" : "translateX(-50%)";

/**
 * A trace waterfall, styled: `createTimeline({ rows })` owns the extent (so every bar is a percentage of the whole
 * trace), each row's `aria-level` and `aria-current`, the `data-status` hook, the roving tab stop and the keys that move
 * it, the selection request, the `--depth` of the label and the ruler's ticks and labels.
 *
 * The skin owns the frame (surface, border, radius and the theme's tokens in light and dark), the name column and its
 * indent, the track and the bar's tone per status, the ruler's lines and labels, the duration column derived from
 * `start` / `end`, the selected and hover looks, the focus ring, and the polite status line that reads the selected span.
 * It also moves the real DOM focus to the row the primitive made its tab stop, as the primitive leaves that to the host.
 *
 * The rows mode has no zoom (the demo tree does); a trace that ships zoom is a page's own window over the same rows.
 */
export const Timeline = (props: TimelineProps): JSX.Element => {
  const timeline = createTimeline({
    rows: props.spans,
    get axis() {
      return props.unit === undefined ? undefined : { unit: props.unit };
    },
    get selected() {
      return props.selected;
    },
    get onSelect() {
      return props.onSelect;
    },
  });
  untrack(() => props.onReady)?.(timeline);

  let list: HTMLUListElement | undefined;
  // The primitive changes the tab stop; the skin moves the real focus, but only once the reader is in the list, so
  // mounting the trace does not take the page's focus.
  const [engaged, setEngaged] = createSignal(false);

  createEffect(
    () => ({ id: timeline.focusedId(), engaged: engaged() }),
    (state) => {
      if (state.id === undefined || !state.engaged || list === undefined) {
        return;
      }
      const row = list.querySelector<HTMLElement>(`[data-id="${CSS.escape(state.id)}"]`);
      if (row !== null && row !== document.activeElement) {
        row.focus();
      }
    },
  );

  const unit = (): string => props.unit ?? "ms";
  const total = (): number => {
    const extent = timeline.extent();
    return extent.end - extent.start;
  };
  // One formatter for a duration and for a tick's axis, rounded to the thousandth the geometry uses.
  const format = (value: number): string => `${Math.round(value * 1000) / 1000} ${unit()}`;

  const selectedSpan = (): TimelineSpan | undefined => {
    const id = timeline.selectedId();
    return id === undefined ? undefined : props.spans.find((span) => span.id === id);
  };

  // The announced value is the selected span, not the cursor: the cursor is the tab stop (and what a screen reader
  // reads as the focused listitem), while Enter, Space or a click is the selection this line repeats.
  const status = (): string => {
    const span = selectedSpan();
    if (span === undefined) {
      return "No span selected.";
    }
    return `${span.label} — ${format(span.end - span.start)} of ${format(total())}.`;
  };

  const ticks = (): ReadonlyArray<TimelineTick> => timeline.rulerProps.ticks;

  return (
    <div data-part="timeline-root" class={css.cn(rootClass, props.class)}>
      <div data-part="timeline-frame" class={frameClass}>
        <div data-part="timeline-ruler-row" aria-hidden="true" class={rulerRowClass}>
          <span class={captionClass}>Span</span>
          <div {...timeline.rulerProps} data-part="timeline-ruler" class={rulerTrackClass}>
            <For each={ticks()}>
              {(tick, index) => (
                <span
                  data-part="timeline-tick"
                  class={tickClass}
                  style={{ left: `${tick.left}%` }}
                >
                  <span
                    class={tickLabelClass}
                    style={{ transform: tickShift(index(), ticks().length) }}
                  >
                    {tick.label}
                  </span>
                </span>
              )}
            </For>
          </div>
          <span class={css.cn(captionClass, durationClass)}>Duration</span>
        </div>
        <ul
          {...timeline.listProps}
          data-part="timeline-list"
          aria-label={props.label ?? DEFAULT_LABEL}
          class={listClass}
          ref={(node: HTMLUListElement) => {
            list = node;
          }}
          onPointerDown={() => setEngaged(true)}
          onFocusIn={() => setEngaged(true)}
        >
          <For each={props.spans}>
            {(span) => (
              <li
                {...timeline.rowProps(span.id)}
                data-part="timeline-row"
                data-id={span.id}
                class={rowClass}
              >
                <span
                  {...timeline.labelProps(span.id)}
                  data-part="timeline-label"
                  class={labelClass}
                >
                  {span.label}
                </span>
                <span class={trackClass}>
                  <span
                    {...timeline.barProps(span.id)}
                    data-part="timeline-bar"
                    class={barClass}
                    style={timeline.barProps(span.id).style}
                  />
                </span>
                <span data-part="timeline-duration" class={durationClass}>
                  {format(span.end - span.start)}
                </span>
              </li>
            )}
          </For>
        </ul>
      </div>
      <p data-part="timeline-status" role="status" aria-live="polite" class={statusClass}>
        {status()}
      </p>
      <p data-part="timeline-hint" class={hintClass}>
        {props.hint ?? DEFAULT_HINT}
      </p>
    </div>
  );
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import { render } from "@solidjs/web";
import type { JSX } from "@solidjs/web";
import type { TimelineRows, TimelineSpan } from "@cssints/headless";
import { createSignal } from "solid-js";

import { Timeline, type TimelineProps } from "./timeline.tsx";

/**
 * One checkout request as a trace: the root, the work it did in two branches, and the nested database call inside the
 * auth branch. The numbers are the request's own fraction of time, 0 to 1, so the bars read as shares of the whole.
 */
export const TIMELINE_SPANS: ReadonlyArray<TimelineSpan> = [
  { id: "request", label: "GET /checkout", start: 0, end: 1, depth: 0, status: "ok" },
  {
    id: "auth",
    label: "auth: verify session",
    start: 0.03,
    end: 0.26,
    depth: 1,
    status: "ok",
  },
  { id: "db", label: "db: SELECT cart", start: 0.08, end: 0.22, depth: 2, status: "error" },
  {
    id: "render",
    label: "render: checkout page",
    start: 0.55,
    end: 0.97,
    depth: 1,
    status: "unset",
  },
];

/** The trace is normalized: 1 is the whole request, so the ruler reads seconds of it. */
export const TIMELINE_UNIT = "s" as const;

/** The list's accessible name: the request this trace belongs to. */
export const TIMELINE_LABEL = "Checkout request";

/** The one sentence the demo says about its keys. */
export const TIMELINE_HINT =
  "Keys: ↑ and ↓ move between spans, Home and End jump to the ends, and Enter or Space selects one — the status line repeats the span and its share of the request.";

/** The span the demo starts with: the root, so the status line has a value before anyone clicks. */
export const TIMELINE_SELECTED = "request";

export interface TimelineExampleProps {
  readonly class?: string | undefined;
  /** The primitive, for a test or a page that reads it. */
  readonly onReady?: TimelineProps["onReady"];
}

/**
 * The starter in ordinary use: a trace with one nested span, the selected root painted, the ruler over the whole extent
 * and a sentence about the keys. A page copies this and swaps `TIMELINE_SPANS` for its own trace.
 */
export const TimelineExample = (props: TimelineExampleProps): JSX.Element => {
  const [selected, setSelected] = createSignal<string>(TIMELINE_SELECTED);
  return (
    <Timeline
      class={props.class}
      spans={TIMELINE_SPANS}
      unit={TIMELINE_UNIT}
      label={TIMELINE_LABEL}
      selected={selected()}
      onSelect={setSelected}
      hint={TIMELINE_HINT}
      onReady={props.onReady}
    />
  );
};

/** What a mounted demo hands the test: where it lives, the primitive, and a teardown. */
export interface MountedTimeline {
  readonly root: HTMLElement;
  readonly api: TimelineRows;
  readonly dispose: () => void;
}

/** The demo's width, so the track has the same room in every test run. */
const DEMO_WIDTH = 640;

/** Mounts the styled trace at a 640 px frame. The primitive owns the layout, the cursor and the selection. */
export const mountTimeline = (): MountedTimeline => {
  const root = document.createElement("div");
  root.style.width = `${DEMO_WIDTH}px`;
  document.body.append(root);
  let api: TimelineRows | undefined;
  const dispose = render(
    () => (
      <TimelineExample
        onReady={(timeline) => {
          api = timeline;
        }}
      />
    ),
    root,
  );
  if (api === undefined) {
    throw new Error("timeline fixture: the primitive did not mount");
  }
  return {
    root,
    api,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

import { afterEach, describe, expect, it } from "vite-plus/test";
import { userEvent } from "vite-plus/test/browser";

import {
  TIMELINE_LABEL,
  TIMELINE_SPANS,
  type MountedTimeline,
  mountTimeline,
} from "./timeline.fixture";

// @cssints/headless checks the rows mode on its own fixture in test/timeline-rows.browser.test.tsx; the rows mode has no
// APG pattern, so that file is the primitive's oracle. This file is the skin's: it mounts the starter in a real Chromium,
// reads the geometry the primitive put on the bars, and drives the cursor, the selection and the focus ring the way a
// reader does. The trace is normalized: its whole extent is 1 s, so a span's start and duration are its percentages.

/** Solid 2 applies setters and the primitive's effects on later turns. */
const settle = (): Promise<void> => new Promise((resolve) => setTimeout(resolve, 20));

/** A frame for the computed styles, after a focus-visible state has been applied. */
const frame = (): Promise<void> =>
  new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => resolve())));

/** Polls until `done` holds, so the row's colour transition is waited for rather than assumed. */
const waitFor = async (done: () => boolean, limit = 2000): Promise<void> => {
  const start = performance.now();
  while (!done()) {
    if (performance.now() - start > limit) {
      throw new Error("waitFor timed out");
    }
    await settle();
  }
};

const live: MountedTimeline[] = [];

const mounted = (): MountedTimeline => {
  const instance = mountTimeline();
  live.push(instance);
  return instance;
};

afterEach(() => {
  for (const instance of live.splice(0)) {
    instance.dispose();
  }
});

const required = <T extends Element>(parent: ParentNode, selector: string): T => {
  const element = parent.querySelector<T>(selector);
  if (element === null) {
    throw new Error(`timeline: no ${selector}`);
  }
  return element;
};

const row = (root: ParentNode, id: string): HTMLElement =>
  required(root, `[data-part="timeline-row"][data-id="${id}"]`);

const bar = (root: ParentNode, id: string): HTMLElement =>
  required(root, `[data-part="timeline-row"][data-id="${id}"] [data-part="timeline-bar"]`);

const status = (root: ParentNode): HTMLElement => required(root, '[data-part="timeline-status"]');

/** A key on the focused row, as a reader's would arrive. */
const press = async (key: string): Promise<void> => {
  const active = document.activeElement;
  if (!(active instanceof HTMLElement)) {
    throw new Error("timeline: nothing has the focus");
  }
  active.dispatchEvent(new KeyboardEvent("keydown", { key, bubbles: true, cancelable: true }));
  await settle();
};

describe("Timeline", () => {
  it("is a named list of spans, with the primitive's levels and a decorative ruler", async () => {
    const { root, api } = mounted();
    await settle();

    const list = required(root, '[data-part="timeline-list"]');
    expect(list.getAttribute("role")).toBe("list");
    expect(list.getAttribute("aria-label")).toBe(TIMELINE_LABEL);
    expect(root.querySelectorAll('[data-part="timeline-row"]')).toHaveLength(TIMELINE_SPANS.length);
    expect(
      [...root.querySelectorAll('[data-part="timeline-row"]')].every(
        (element) => element.getAttribute("role") === "listitem",
      ),
    ).toBe(true);

    // the nesting a flat list cannot show in the DOM is the primitive's aria-level, not a second copy here
    expect(row(root, "request").getAttribute("aria-level")).toBe("1");
    expect(row(root, "auth").getAttribute("aria-level")).toBe("2");
    expect(row(root, "db").getAttribute("aria-level")).toBe("3");
    expect(row(root, "render").getAttribute("aria-level")).toBe("2");

    const nested = required(row(root, "db"), '[data-part="timeline-label"]');
    expect(nested.style.getPropertyValue("--depth")).toBe("2");
    expect(parseFloat(getComputedStyle(nested).paddingInlineStart)).toBeCloseTo(24, 0);

    // the ruler is decoration; its ticks are exactly the primitive's, at the primitive's positions
    const ruler = required(root, '[data-part="timeline-ruler"]');
    expect(ruler.getAttribute("role")).toBe("presentation");
    expect(ruler.getAttribute("aria-hidden")).toBe("true");
    const ticks = [...root.querySelectorAll<HTMLElement>('[data-part="timeline-tick"]')];
    expect(ticks.map((tick) => tick.textContent)).toEqual(
      api.rulerProps.ticks.map((tick) => tick.label),
    );
    expect(ticks).toHaveLength(api.rulerProps.ticks.length);
    for (const [index, tick] of api.rulerProps.ticks.entries()) {
      expect(parseFloat(ticks[index]?.style.left ?? "")).toBeCloseTo(tick.left, 6);
    }
    expect(ticks.length).toBeGreaterThanOrEqual(4);
    expect(ticks[0]?.textContent).toBe("0.0 s");
  });

  it("draws one bar per span at the primitive's percentages of the whole extent", async () => {
    const { root, api } = mounted();
    await settle();

    for (const span of TIMELINE_SPANS) {
      const element = bar(root, span.id);
      const geometry = api.barProps(span.id).style;
      expect(element.style.left).toBe(geometry.left);
      expect(element.style.width).toBe(geometry.width);
    }

    // start / duration against the 1 s extent, read straight off the style
    expect(bar(root, "request").style.left).toBe("0%");
    expect(bar(root, "request").style.width).toBe("100%");
    expect(bar(root, "auth").style.left).toBe("3%");
    expect(bar(root, "auth").style.width).toBe("23%");
    expect(bar(root, "db").style.left).toBe("8%");
    expect(bar(root, "db").style.width).toBe("14%");
    expect(bar(root, "render").style.left).toBe("55%");
    expect(bar(root, "render").style.width).toBe("42%");

    // the grandchild is drawn inside its parent's range: its left starts after the parent's and its end is before it
    const parent = api.barProps("auth").style;
    const child = api.barProps("db").style;
    const parentLeft = parseFloat(parent.left);
    const parentRight = parentLeft + parseFloat(parent.width);
    const childLeft = parseFloat(child.left);
    const childRight = childLeft + parseFloat(child.width);
    expect(childLeft).toBeGreaterThanOrEqual(parentLeft);
    expect(childRight).toBeLessThanOrEqual(parentRight);

    // the tone is the primitive's data-status, and the root and the error span do not share it
    expect(row(root, "request").getAttribute("data-status")).toBe("ok");
    expect(row(root, "db").getAttribute("data-status")).toBe("error");
    expect(getComputedStyle(bar(root, "db")).backgroundColor).not.toBe(
      getComputedStyle(bar(root, "render")).backgroundColor,
    );
  });

  it("moves the cursor with the arrows, Home and End, and the announcement follows the selection", async () => {
    const { root } = mounted();
    await settle();

    // the first row is the primitive's tab stop before anyone asks for another
    expect(row(root, "request").tabIndex).toBe(0);
    expect(row(root, "auth").tabIndex).toBe(-1);
    expect(status(root).textContent).toContain("GET /checkout");

    row(root, "request").focus();
    await settle();

    // the primitive moves the tab stop; the skin moves the real focus after it
    await press("ArrowDown");
    expect(document.activeElement).toBe(row(root, "auth"));
    expect(row(root, "auth").tabIndex).toBe(0);
    expect(row(root, "request").tabIndex).toBe(-1);
    // moving the cursor is not selecting: the announced value still names the root
    expect(status(root).textContent).toContain("GET /checkout");

    await press("Enter");
    expect(row(root, "auth").getAttribute("aria-current")).toBe("true");
    expect(row(root, "request").hasAttribute("aria-current")).toBe(false);
    expect(status(root).textContent).toContain("auth: verify session");

    await press("End");
    expect(document.activeElement).toBe(row(root, "render"));
    await press(" ");
    expect(row(root, "render").getAttribute("aria-current")).toBe("true");
    expect(status(root).textContent).toContain("render: checkout page");

    await press("Home");
    expect(document.activeElement).toBe(row(root, "request"));
  });

  it("paints the selected row from aria-current, and a click moves both the selection and the tab stop", async () => {
    const { root } = mounted();
    await settle();

    const plain = getComputedStyle(row(root, "auth")).backgroundColor;
    // the demo starts with the root selected, so the selected look is on it and not on its child
    expect(row(root, "request").getAttribute("aria-current")).toBe("true");
    expect(getComputedStyle(row(root, "request")).backgroundColor).not.toBe(plain);

    await userEvent.click(row(root, "auth"));
    await settle();

    expect(row(root, "auth").getAttribute("aria-current")).toBe("true");
    expect(row(root, "request").hasAttribute("aria-current")).toBe(false);
    expect(getComputedStyle(row(root, "auth")).backgroundColor).not.toBe(plain);
    await waitFor(() => getComputedStyle(row(root, "request")).backgroundColor === plain);
    expect(document.activeElement).toBe(row(root, "auth"));
    expect(status(root).textContent).toContain("auth: verify session");
  });

  it("draws the focus ring when Tab reaches the tab stop", async () => {
    const { root } = mounted();
    await settle();

    (document.activeElement as HTMLElement | null)?.blur();
    await userEvent.keyboard("{Tab}");
    await frame();

    const focused = document.activeElement;
    expect(focused).toBe(row(root, "request"));
    const style = getComputedStyle(focused as HTMLElement);
    expect(style.outlineStyle).toBe("solid");
    expect(parseFloat(style.outlineWidth)).toBeGreaterThanOrEqual(2);
    expect(root.contains(focused)).toBe(true);
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
